for (let t = 0; t < 12; t++) {
  const st = sdk.getState();
  if (!st.player.dead && st.player.hitpoints > 0) break;
  await new Promise(r => setTimeout(r, 1000));
}
const w = await bot.walkTo(3252, 3230, 5, { timeout: 45_000 });
const s = sdk.getState();
const gob = s.nearbyNpcs.filter(n => /goblin/i.test(n.name)).map(n => `L${n.combatLevel} d${n.distance}${n.unreachable ? 'U' : ''}`);
return { walk: w.success, pos: [s.player.worldX, s.player.worldZ], hp: s.player.hitpoints, gob, msLeft: deadline - Date.now() };

const deadline = Date.parse("2026-10-21T12:36:16.043Z");
let res;
for (let i = 0; i < 3; i++) {
  if (Date.now() > deadline - 45_000) break;
  const s = sdk.getState();
  const npc = s.nearbyNpcs.filter(n => /^duck$/i.test(n.name) && n.optionsWithIndex.some(o => /attack/i.test(o.text))).sort((a,b)=>a.distance-b.distance)[0];
  if (!npc) { res = 'no-duck-option'; break; }
  try { await bot.attack(npc); } catch (e) { res = 'err:' + (e.message||'').slice(0,40); }
  for (let t = 0; t < 15; t++) {
    await new Promise(r => setTimeout(r, 1000));
    const st = sdk.getState();
    if (!st.nearbyNpcs.find(n => n.index === npc.index)) { res = 'DUCK KILLED'; break; }
  }
  if (res === 'DUCK KILLED') break;
}
const s = sdk.getState();
return { res, pos: [s.player.worldX, s.player.worldZ], hp: s.player.hitpoints, msLeft: deadline - Date.now(),
  att: s.nearbyNpcs.map(n => `${n.name}L${n.combatLevel}d${n.distance}`).slice(0, 12) };

const deadline = Date.parse("2026-10-21T12:36:16.043Z");
sdk.say("If you havent killed Imp yet I'm hunting it around spawn - otherwise tell me a new name to get");
let found = null;
for (let i = 0; i < 5 && Date.now() < deadline - 60_000; i++) {
  const s = sdk.getState();
  const imp = s.nearbyNpcs.filter(n => /^imp$/i.test(n.name) && !n.unreachable).sort((a,b)=>a.distance-b.distance)[0];
  if (imp) { found = imp; break; }
  await bot.walkTo(3228 + (i%2)*10, 3238 + (i%3)*6, 3, { timeout: 15_000 });
}
let res = 'none seen';
if (found) {
  try { await bot.attack(found); } catch (e) {}
  for (let t = 0; t < 15; t++) {
    await new Promise(r => setTimeout(r, 1000));
    if (!sdk.getState().nearbyNpcs.find(n => n.index === found.index)) { res = 'IMP KILLED L' + found.combatLevel; break; }
  }
}
return { res, msLeft: deadline - Date.now(), pos: (()=>{const p=sdk.getState().player;return [p.worldX,p.worldZ];})() };

